    timerId = null;
    pending = false;

    if (!trailing) return;
    if (leadingInvoked && callCount === 1) return;
    if (lastArgs === null) return;

    const args = lastArgs;
    lastArgs = null;
    leadingInvoked = false;
    callCount = 0;

    fn(...args);
